import {rooms as initialRooms,messages as initialMessages,people} from './data.js';
import {extractTasks,summarize,search} from './analysis.js';
const icons={hash:'<path d="M4 9h16M3 15h16M11 3 7 21M17 3l-4 18"/>',sparkles:'<path d="m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3ZM20 2v4M18 4h4"/>',search:'<circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z"/>',check:'<path d="m5 12 4 4L19 6"/>',tasks:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M9 3h6v4H9zM8 13l2 2 5-5"/>',bookmark:'<path d="M6 21V4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v17l-6-4-6 4Z"/>',settings:'<path d="m9 3-1 3-3 1 1 4-2 2 3 3v3l4 1 2-2 4 1 2-3-1-3 2-3-3-2V5l-4-1-2 2-2-3Z"/><circle cx="12" cy="12" r="3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 17h.01"/>',send:'<path d="m3 3 19 9-19 9 4-9-4-9ZM7 12h15"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',coffee:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V8ZM17 9h2a3 3 0 0 1 0 6h-2M7 3v2M12 3v2"/>',palette:'<circle cx="8" cy="9" r=".5"/><circle cx="12" cy="6" r=".5"/><circle cx="17" cy="9" r=".5"/><path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 0-4h-1a2 2 0 0 1 0-4h5a4 4 0 0 0 4-4c0-3-5-6-9-6Z"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M2 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H4v17h17v-6"/>',smile:'<circle cx="12" cy="12" r="9"/><path d="M8 14a4 4 0 0 0 8 0M8 9h.01M16 9h.01"/>',leaf:'<path d="M20 3C4 2 2 10 7 16c7 6 14-2 13-13ZM4 21 16 9"/>',logout:'<path d="M9 4H4v16h5m6-4 4-4-4-4M8 12h13"/>'};
const I=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.hash}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function saved(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let rooms=saved('nw-rooms',initialRooms),messages=saved('nw-messages',initialMessages),bookmarks=saved('nw-bookmarks',[]),user=localStorage.getItem('nw-user')||'',room='project',tab='chat',aiMode='summary',answer=null,filter='',server=false,busy=false;
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
function persist(){try{localStorage.setItem('nw-rooms',JSON.stringify(rooms));localStorage.setItem('nw-messages',JSON.stringify(messages));localStorage.setItem('nw-bookmarks',JSON.stringify(bookmarks))}catch{toast('저장 공간이 부족해요. 브라우저 설정을 확인해 주세요.')}}
const current=()=>rooms.find(r=>r.id===room)||rooms[0];const list=()=>messages.filter(m=>m.room===room);const initials=n=>n.slice(-2);const color=n=>people.find(p=>p.name===n)?.color||'olive';
const avatar=(n,small=false)=>`<span class="avatar ${color(n)} ${small?'small':''}">${esc(initials(n))}</span>`;
const time=t=>new Date(t).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false});
const date=t=>new Date(t).toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'});
const badge=s=>`<span class="badge ${s==='완료'?'done':s==='진행 중'?'progress':'unknown'}">${s==='완료'?I('check',12):'<span class="dot"></span>'}${s}</span>`;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200)}
function render(){app.innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="NeoWork 홈"><span class="brand-mark">N<span></span></span>NeoWork<span class="beta">BETA</span></a><button class="workspace" data-action="workspace"><span class="workspace-mark">N</span><span><strong>네오워크 팀</strong><small>우리의 아이디어가 자라는 곳</small></span>${I('down',16)}</button><div class="side-nav"><button data-action="all-tasks">${I('tasks')}<span>내 업무</span><span class="count">${extractTasks(messages).filter(t=>t.name===(user||'김민지')&&t.status!=='완료').length}</span></button><button data-action="saved">${I('bookmark')}<span>저장한 메시지</span>${bookmarks.length?`<span class="count">${bookmarks.length}</span>`:''}</button></div><div class="nav-label"><span>워크스페이스</span><button data-action="new-room" aria-label="채팅방 만들기">${I('plus',16)}</button></div><nav class="channels">${rooms.map(r=>`<button class="${room===r.id?'active':''}" data-room="${esc(r.id)}">${I(r.icon)}<span>${esc(r.name)}</span>${room===r.id?'<span class="active-dot"></span>':''}</button>`).join('')}</nav><button class="add-channel" data-action="new-room">${I('plus',17)}새 채팅방 만들기</button><div class="team-label nav-label"><span>함께하는 팀원</span><span>${people.length}</span></div><div class="people">${people.map(p=>`<button data-person="${p.name}">${avatar(p.name,true)}<span>${p.name}</span><span class="presence"></span></button>`).join('')}</div><div class="sidebar-bottom"><div class="little-note">${I('leaf',23)}<span>좋은 대화가<br><strong>더 나은 팀을 만듭니다.</strong></span></div><button class="help-button" data-action="help">${I('help',17)}도움말 및 가이드${I('external',14)}</button><button class="profile" data-action="profile">${avatar(user||'게스트',true)}<span><strong>${esc(user||'이름으로 시작하기')}</strong><small>${user?'함께 일하는 중':'편하게 둘러보세요'}</small></span>${I('settings',18)}</button></div></aside><div class="main-shell"><header class="global-header"><div class="breadcrumb">워크스페이스 ${I('chevron',13)}<strong>네오워크 팀</strong></div><div class="header-right"><span class="mode-label"><span class="presence"></span>${server?'공유 서버 연결됨':'브라우저 체험 모드'}</span><button data-action="global-search" class="icon-button" aria-label="대화 검색">${I('search')}</button><button class="icon-button" data-action="help" aria-label="도움말">${I('help')}</button></div></header><div class="work-area"><main class="conversation"><header class="room-header"><div class="room-title"><span class="room-icon">${I(current().icon,25)}</span><div><h1>${esc(current().name)}</h1><p>${esc(current().description)}</p></div></div><button class="member-button" data-action="members" aria-label="팀원 보기"><span class="avatar-stack">${people.slice(0,3).map(p=>avatar(p.name,true)).join('')}</span><span>${people.length}명</span>${I('down',13)}</button></header><div class="room-toolbar"><nav class="tabs">${[['chat','chat','대화'],['tasks','tasks','업무'],['saved','bookmark','저장됨']].map(([id,ic,label])=>`<button class="${tab===id?'selected':''}" data-tab="${id}">${I(ic,17)}${label}${id==='tasks'?`<span>${extractTasks(list()).length}</span>`:''}</button>`).join('')}</nav><button class="summary-button" data-action="summary">${I('sparkles',16)}대화 요약</button></div><div class="content-area" id="content">${mainContent()}</div>${tab==='chat'?composer():''}</main><aside class="ai-panel"><div class="ai-header"><span class="ai-logo">${I('sparkles',20)}</span><strong>Neo AI</strong><span class="ai-pill">팀의 두 번째 기억</span></div><div class="ai-scroll" id="ai-scroll"><div class="ai-intro"><span class="eyebrow">LESS SCROLLING, MORE DOING</span><h2>대화의 흐름을,<br>한눈에 담아요<span>✳</span></h2><p>놓친 이야기는 정리하고,<br>다음에 할 일은 더 선명하게.</p></div><div class="ai-switch"><button class="${aiMode==='summary'?'selected':''}" data-ai="summary">${I('sparkles',15)}대화 요약</button><button class="${aiMode==='tasks'?'selected':''}" data-ai="tasks">${I('tasks',15)}업무 모아보기</button></div><div id="ai-result">${aiContent()}</div><div class="ask-section"><span class="section-overline">이렇게 물어보세요</span>${['내가 해야 할 업무가 있니?','이서연의 업무는 완료됐니?','회의에서 결정된 내용이 뭐야?'].map(q=>`<button class="suggestion" data-question="${q}"><span>${q}</span>${I('arrow',14)}</button>`).join('')}</div></div><div class="ai-bottom"><form id="ask-form"><label class="sr-only" for="question">대화에 대해 질문하기</label><input id="question" placeholder="대화에 대해 무엇이든 물어보세요" maxlength="500" autocomplete="off"><button aria-label="질문 보내기" ${busy?'disabled':''}>${I('arrow',18)}</button></form><p>${I('help',11)}${server?'대화 기록 기반 분석 · 근거를 함께 확인하세요':'체험 모드 · 규칙 기반 분석, 이 브라우저에 저장'}</p></div></aside></div></div>`;bind();}
function mainContent(){let ms=list();if(filter)ms=ms.filter(m=>m.text.includes(filter)||m.name.includes(filter));if(tab==='tasks'){const ts=extractTasks(list());return `<div class="view-heading"><span class="eyebrow">TEAM TO-DOS</span><h2>대화가 업무로 이어지는 곳</h2><p>대화에서 확인한 담당자와 진행 상황이에요.</p></div><div class="task-filters"><button class="chip active" data-task-filter="all">전체 ${ts.length}</button><button class="chip" data-task-filter="mine">내 업무</button></div><div id="task-list">${tasksHTML(ts,true)}</div>`}if(tab==='saved'){ms=ms.filter(m=>bookmarks.includes(m.id));return `<div class="view-heading"><span class="eyebrow">SAVED FOR LATER</span><h2>다시 보고 싶은 이야기</h2><p>메시지의 북마크 버튼으로 중요한 대화를 모아보세요.</p></div>${ms.length?ms.map(messageHTML).join(''):'<div class="empty">아직 저장한 메시지가 없어요.</div>'}`}
return `${filter?`<div class="search-banner">“${esc(filter)}” 검색 결과 ${ms.length}개 <button data-action="clear-filter">${I('close',15)}</button></div>`:''}<div class="channel-welcome"><span class="welcome-icon">${I(current().icon,29)}</span><h2>우리의 다음을 만드는 대화</h2><p><strong># ${esc(current().name)}</strong> 채팅방의 시작이에요.<br>아이디어를 나누고, 함께 한 걸음씩 나아가요.</p></div><div class="context-note">${I('sparkles',16)}<span>대화에 집중하세요. 중요한 내용은 <strong>Neo AI</strong>가 함께 정리해요.</span></div>${ms.length?ms.map((m,i)=>`${i===0||date(m.time)!==date(ms[i-1].time)?`<div class="date-divider"><span>${date(m.time)}</span></div>`:''}${messageHTML(m)}`).join(''):'<div class="empty">아직 대화가 없어요. 첫 인사를 남겨보세요!</div>'}`}
function messageHTML(m){return `<article class="message" id="msg-${esc(m.id)}">${avatar(m.name)}<div class="message-body"><div class="message-meta"><strong>${esc(m.name)}</strong>${m.name===(user||'김민지')?'<span class="me-tag">나</span>':''}<time datetime="${m.time}">${time(m.time)}</time></div><p>${esc(m.text).replace(/\n/g,'<br>')}</p></div><button class="save-message ${bookmarks.includes(m.id)?'is-saved':''}" data-bookmark="${esc(m.id)}" aria-label="${bookmarks.includes(m.id)?'저장 취소':'메시지 저장'}">${I('bookmark',16)}</button></article>`}
function composer(){return `<div class="composer-wrap"><form id="message-form"><label class="sr-only" for="message">메시지</label><textarea id="message" placeholder="# ${esc(current().name)}에 메시지 보내기" rows="2" maxlength="4000"></textarea><div class="composer-tools"><button type="button" class="icon-button" data-action="emoji" aria-label="이모지 넣기">${I('smile',20)}</button><span>서로를 존중하는 한마디로 시작해요.</span><button class="send-button" aria-label="메시지 전송">보내기 ${I('send',15)}</button></div></form><div class="composer-caption"><span><kbd>Enter</kbd> 전송 · <kbd>Shift + Enter</kbd> 줄바꿈</span><span>${I('check',12)}${server?'서버에 안전하게 저장':'이 브라우저에 자동 저장'}</span></div></div>`}
function sourceButton(id,label='근거 메시지 보기'){return `<button class="source-link" data-source="${esc(id)}">${label} ${I('arrow',12)}</button>`}
function tasksHTML(ts,full=false){return ts.length?ts.map(t=>`<div class="task-card ${full?'full-task':''}"><div class="task-title">${I(t.status==='완료'?'check':'tasks',16)}<strong>${esc(t.title)}</strong></div><div class="task-meta">${avatar(t.name,true)}<span>${esc(t.name)}</span>${badge(t.status)}</div>${full?`<p>${I('clock',13)}${esc(t.due)}</p>`:''}${sourceButton(t.sources.at(-1))}</div>`).join(''):'<div class="empty">대화에서 확인된 업무가 없어요.</div>'}
function aiContent(){if(answer)return `<div class="answer-card"><div class="answer-question">${I('chat',15)}${esc(answer.question)}</div><p>${esc(answer.text)}</p>${tasksHTML(answer.tasks||[])}${(answer.sources||[]).filter(id=>!(answer.tasks||[]).some(t=>t.sources.includes(id))).map(id=>{const m=messages.find(m=>m.id===id);return m?`<div class="evidence"><strong>${esc(m.name)}</strong><p>${esc(m.text)}</p>${sourceButton(id,'대화로 이동')}</div>`:''}).join('')}<button class="text-button" data-action="reset-ai">${I('sparkles',13)}요약으로 돌아가기</button></div>`;if(aiMode==='tasks')return `<div class="section-title"><h3>팀의 다음 할 일</h3><span>${extractTasks(list()).length}건</span></div>${tasksHTML(extractTasks(list()))}`;const s=summarize(list());const done=extractTasks(list()).filter(t=>t.status==='완료').length;return `<div class="summary-meta"><span><span class="presence"></span>최근 대화 ${list().length}개 분석</span><button data-action="refresh-summary" aria-label="요약 새로고침">↻</button></div><section class="summary-card"><h3><span class="section-icon olive">${I('chat',15)}</span>핵심 논의</h3>${s.topics.length?s.topics.map(m=>`<p class="summary-item">${esc(m.text)} ${sourceButton(m.id,'↗')}</p>`).join(''):'<p class="muted">주요 논의가 쌓이면 여기에 정리돼요.</p>'}<div class="mini-stats"><span><strong>${extractTasks(list()).length}</strong> 확인된 업무</span><span><strong>${done}</strong> 완료된 업무</span></div></section><section class="summary-card"><h3><span class="section-icon orange">${I('check',15)}</span>결정 사항</h3>${s.decisions.length?s.decisions.map(m=>`<p class="summary-item">${esc(m.text)} ${sourceButton(m.id,'↗')}</p>`).join(''):'<p class="muted">명시적으로 결정된 내용이 아직 없어요.</p>'}</section><section class="summary-card"><h3><span class="section-icon blue">${I('clock',15)}</span>남은 업무 <span class="number">${s.issues.length}</span></h3>${s.issues.length?s.issues.map(t=>`<div class="remaining-task"><span class="task-bullet"></span><div><strong>${esc(t.title)}</strong><small>${esc(t.name)} · ${esc(t.due)}</small></div>${sourceButton(t.sources.at(-1),'↗')}</div>`).join(''):'<p class="muted">확인된 진행 중 업무가 없어요.</p>'}</section><div class="grounded">${I('check',13)}대화 기록에 있는 내용만 정리했어요.</div>`}
function bind(){document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{room=b.dataset.room;tab='chat';filter='';answer=null;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;filter='';render()});document.querySelectorAll('[data-ai]').forEach(b=>b.onclick=()=>{aiMode=b.dataset.ai;answer=null;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-bookmark]').forEach(b=>b.onclick=()=>{const id=b.dataset.bookmark;bookmarks=bookmarks.includes(id)?bookmarks.filter(x=>x!==id):[...bookmarks,id];persist();const y=document.querySelector('#content').scrollTop;render();document.querySelector('#content').scrollTop=y});document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>jump(b.dataset.source));document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>person(b.dataset.person));document.querySelectorAll('[data-task-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-task-filter]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#task-list').innerHTML=tasksHTML(extractTasks(list()).filter(t=>b.dataset.taskFilter!=='mine'||t.name===(user||'김민지')),true);document.querySelectorAll('#task-list [data-source]').forEach(x=>x.onclick=()=>jump(x.dataset.source))});document.querySelector('#message-form')?.addEventListener('submit',send);document.querySelector('#message')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send(e)}});document.querySelector('#ask-form')?.addEventListener('submit',e=>{e.preventDefault();ask(document.querySelector('#question').value)});document.querySelector('.brand').onclick=e=>{e.preventDefault();room='project';tab='chat';answer=null;render()}}
function jump(id){const m=messages.find(m=>m.id===id);if(!m)return toast('해당 메시지를 찾지 못했어요.');room=m.room;tab='chat';filter='';render();const el=document.getElementById('msg-'+id);el?.scrollIntoView({behavior:'smooth',block:'center'});el?.classList.add('highlight');setTimeout(()=>el?.classList.remove('highlight'),2500)}
async function send(e){e.preventDefault();const input=document.querySelector('#message');const text=input.value.trim();if(!text)return;if(!user)return profile(()=>{document.querySelector('#message').value=text;send({preventDefault(){}})});const m={id:crypto.randomUUID(),room,name:user,text,time:new Date().toISOString()};if(server){try{const r=await fetch('/api/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(m)});if(!r.ok)throw Error();messages.push(m)}catch{return toast('메시지를 보내지 못했어요. 다시 시도해 주세요.')}}else messages.push(m);persist();answer=null;render();document.querySelector('#content').scrollTop=1e9;document.querySelector('#message')?.focus()}
async function ask(q){q=q.trim();if(!q||busy)return;busy=true;let result=search(list(),q,user||'김민지');if(server){try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,room,user:user||'김민지'})});if(r.ok){const data=await r.json();if(data.answer)result={text:data.answer,sources:data.sources||[],tasks:[]}}}catch{toast('AI 연결을 확인할 수 없어 대화 기록으로 검색했어요.')}}answer={...result,question:q};busy=false;render();document.querySelector('#ai-scroll').scrollTop=180}
function modal(html){dialog.innerHTML=`<button class="dialog-close icon-button" aria-label="닫기">${I('close')}</button>${html}`;dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.showModal()}
function profile(after){modal(`<span class="modal-icon">${I('leaf',26)}</span><h2>반가워요, 팀원님</h2><p>함께 일할 때 사용할 이름을 알려주세요.<br>가입 절차 없이 바로 대화를 시작할 수 있어요.</p><form id="profile-form"><label for="name">이름</label><input id="name" value="${esc(user)}" placeholder="예: 김민지" maxlength="20" required autocomplete="name"><button class="primary-button">${user?'이름 저장':'워크스페이스 시작하기'} ${I('arrow',17)}</button></form>${user?'<button class="text-button" id="logout">이름 접속 종료</button>':''}`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();user=dialog.querySelector('#name').value.trim();if(!user)return;localStorage.setItem('nw-user',user);dialog.close();render();toast(`${user}님, 환영해요!`);after?.()};dialog.querySelector('#logout')?.addEventListener('click',()=>{user='';localStorage.removeItem('nw-user');dialog.close();render()})}
function person(name){const p=people.find(p=>p.name===name);modal(`${avatar(name)}<h2>${esc(name)}</h2><p>${p?.role||'팀원'}</p><h3>대화에서 확인된 업무</h3>${tasksHTML(extractTasks(messages).filter(t=>t.name===name))}`);dialog.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{dialog.close();jump(b.dataset.source)})}
function action(a){if(a==='profile')return profile();if(a==='summary'||a==='refresh-summary'||a==='reset-ai'){answer=null;aiMode='summary';render();if(a!=='reset-ai')toast('최근 대화를 바탕으로 요약을 업데이트했어요.');return}if(a==='all-tasks'){tab='tasks';render();document.querySelector('[data-task-filter="mine"]').click();return}if(a==='saved'){tab='saved';render();return}if(a==='clear-filter'){filter='';render();return}if(a==='emoji'){const el=document.querySelector('#message');el.value+=' 🙌';el.focus();return}if(a==='global-search'){modal(`<h2>대화 검색</h2><p>현재 채팅방에서 메시지나 작성자를 찾아보세요.</p><form id="search-form"><label for="search">검색어</label><input id="search" required placeholder="검색어 또는 이름"><button class="primary-button">${I('search',17)}검색하기</button></form>`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();filter=dialog.querySelector('input').value.trim();tab='chat';dialog.close();render()};return}if(a==='new-room'){modal(`<h2>새로운 대화의 시작</h2><p>팀의 다음 아이디어를 위한 공간을 만드세요.</p><form><label for="room-name">채팅방 이름</label><input id="room-name" maxlength="40" required placeholder="예: 다음 스프린트"><label for="room-desc">소개</label><input id="room-desc" maxlength="150" placeholder="어떤 이야기를 나눌 공간인가요?"><button class="primary-button">채팅방 만들기 ${I('plus',17)}</button></form>`);dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const n=dialog.querySelector('#room-name').value.trim();if(!n)return;const r={id:crypto.randomUUID(),name:n,description:dialog.querySelector('#room-desc').value.trim()||'함께 이야기를 나누는 공간',icon:'hash'};if(server){try{const res=await fetch('/api/rooms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(r)});if(!res.ok)throw Error()}catch{return toast('채팅방을 만들지 못했어요.')}}rooms.push(r);room=r.id;tab='chat';answer=null;persist();dialog.close();render()};return}if(a==='members'){modal(`<h2>함께하는 팀원</h2><p>같은 목표를 향해, 각자의 자리에서.</p>${people.map(p=>`<div class="member-row">${avatar(p.name)}<span><strong>${p.name}</strong><small>${p.role}</small></span></div>`).join('')}<p class="fine-print">체험 데이터의 팀원 목록입니다. 접속 상태를 의미하지 않습니다.</p>`);return}if(a==='workspace'){modal(`<span class="modal-icon">N</span><h2>네오워크 팀</h2><p>대화에서 다음으로.<br>팀의 대화를 저장하고, 필요한 정보를 다시 찾아보세요.</p><div class="info-box">${server?'공유 서버 모드: 다른 브라우저에서 같은 주소로 접속하면 대화 기록이 동기화됩니다.':'브라우저 체험 모드: 샘플 대화로 시작하며, 작성한 메시지는 현재 브라우저에 저장됩니다. 다른 기기와 공유되지 않습니다.'}</div><p class="fine-print">NeoWork MVP v0.1</p>`);return}if(a==='help'){modal(`<span class="modal-icon">${I('sparkles',26)}</span><h2>대화에서 다음으로</h2><p>NeoWork를 이렇게 사용해 보세요.</p><div class="guide-item"><strong>01 · 이름으로 시작하기</strong><p>왼쪽 아래 프로필에서 이름을 입력하세요.</p></div><div class="guide-item"><strong>02 · 함께 이야기 나누기</strong><p>채팅방을 선택하고 메시지를 보내세요. 메시지 옆 북마크로 중요한 이야기를 저장할 수 있어요.</p></div><div class="guide-item"><strong>03 · 맥락과 업무 확인하기</strong><p>요약·업무 탭을 확인하거나 질문하세요. 근거 메시지를 누르면 원래 대화로 이동해요.</p></div><div class="info-box">${server?'공유 서버에 연결되어 있습니다. Gemini 키가 설정되면 AI 답변을 사용하고, 없으면 규칙 기반 검색으로 동작합니다.':'현재 체험 모드입니다. 요약·검색·업무 추출은 규칙 기반이며 AI 모델을 호출하지 않습니다. 로컬 서버 실행 및 Gemini 연결 방법은 소스의 README를 참고하세요.'}</div>`)} }
render();
async function sync(){try{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok||!r.headers.get('content-type')?.includes('application/json'))return;const d=await r.json();if(!Array.isArray(d.messages)||!Array.isArray(d.rooms))return;const changed=JSON.stringify(d.messages)!==JSON.stringify(messages)||JSON.stringify(d.rooms)!==JSON.stringify(rooms)||!server;server=true;if(changed){const draft=document.querySelector('#message')?.value||'',q=document.querySelector('#question')?.value||'',pos=document.querySelector('#content')?.scrollTop||0;messages=d.messages;rooms=d.rooms;if(!rooms.some(r=>r.id===room))room=rooms[0].id;render();if(document.querySelector('#message'))document.querySelector('#message').value=draft;document.querySelector('#question').value=q;document.querySelector('#content').scrollTop=pos}}catch{if(server)toast('서버 연결이 끊겼어요. 연결을 다시 시도합니다.')}}sync();setInterval(sync,2000);
